const items = $input.all();
const agent5Output = items[0]?.json?.output || '';
const agent7Output = items[1]?.json?.output || '';

// Access system unit costs dynamically from the initial parameter node
const params = $('Load System Parameters').first().json;

const panelCost = Number(params.panel_cost_with_racking) || 350;
const inverterCost = Number(params.inverter_cost) || 5500;
const batteryCost = Number(params.battery_cost) || 5500;
const gridbossCost = Number(params.gridboss_cost) || 2500;
const splitterCost = Number(params.splitter_cost) || 4500;
const panel200aCost = Number(params.panel_200a_cost) || 1500;
const fusedDisconnectCost = 1500;
const bosCost = Number(params.bos_wiring_insulation_breakers_cost) || 7510;

// Default initial state before agent parsing
let quantities = {
  solar_panels: 72,
  flexboss21_inverters: 2,
  gridboss_units: 1,
  eg4_batteries: 8,
  distribution_splitters: 1,
  distribution_panels_200a: 2,
  fused_disconnects_400a: 1,
  annual_generator_kwh: 330.0,
  annual_generator_services: 3,
  annual_generator_cost: 1457.50
};

// DYNAMICALLY EXTRACT AGENT 5's COMPUTED QUANTITIES
let parsedDynamically = false;
const jsonMatch = agent5Output.match(/```json\s*(\{[\s\S]*?\})\s*```/);
if (jsonMatch) {
  try {
    const parsed = JSON.parse(jsonMatch[1]);
    quantities = Object.assign(quantities, parsed);
    parsedDynamically = true;
  } catch (e) {}
}

if (!parsedDynamically) {
  // Regex fallback directly from Agent 5 text
  const pMatch = agent5Output.match(/(\d+)\s*(?:x|×)?\s*(?:panels|JA Solar|modules)/i);
  if (pMatch) quantities.solar_panels = parseInt(pMatch[1], 10);

  const bMatch = agent5Output.match(/(\d+)\s*(?:x|×)?\s*(?:batteries|EG4\s*280|battery)/i);
  if (bMatch) quantities.eg4_batteries = parseInt(bMatch[1], 10);

  const iMatch = agent5Output.match(/(\d+)\s*(?:x|×)?\s*(?:FlexBOSS|inverters)/i);
  if (iMatch) quantities.flexboss21_inverters = parseInt(iMatch[1], 10);
}

// Compute dynamic line items and totals from Agent 5's decision
const pvTotal = quantities.solar_panels * panelCost;
const pvKw = (quantities.solar_panels * 0.44).toFixed(2);
const invTotal = quantities.flexboss21_inverters * inverterCost;
const gbTotal = quantities.gridboss_units * gridbossCost;
const battTotal = quantities.eg4_batteries * batteryCost;
const battKwh = (quantities.eg4_batteries * 14.336).toFixed(1);
const splitTotal = quantities.distribution_splitters * splitterCost;
const pnlTotal = quantities.distribution_panels_200a * panel200aCost;
const discTotal = quantities.fused_disconnects_400a * fusedDisconnectCost;

const equipSubtotal = pvTotal + invTotal + gbTotal + battTotal + splitTotal + pnlTotal + discTotal;
const totalCapex = equipSubtotal + bosCost;
const annualGenCost = Number(quantities.annual_generator_cost) || 1457.50;
const lifecycle10yr = totalCapex + (10 * annualGenCost);

return [{
  json: {
    workflow_title: 'Off-Grid Microgrid 8-Agent Autonomous Design & BOM Optimizer',
    status: 'OPTIMIZATION_COMPLETE',
    bom_generation_mode: parsedDynamically ? 'FULLY_DYNAMIC_FROM_AGENT_5_JSON' : 'DYNAMIC_PARSED_FROM_AGENT_5_TEXT',
    agent_5_selected_quantities: quantities,
    dynamic_bom_summary: {
      solar_panels: `${quantities.solar_panels} x JA Solar 440W (${pvKw} kWdc) @ $${panelCost} = $${pvTotal.toLocaleString('en-CA')}`,
      hybrid_inverters: `${quantities.flexboss21_inverters} x EG4 FlexBOSS21 @ $${inverterCost} = $${invTotal.toLocaleString('en-CA')}`,
      system_controller: `${quantities.gridboss_units} x EG4 GridBOSS MID @ $${gridbossCost} = $${gbTotal.toLocaleString('en-CA')}`,
      battery_storage: `${quantities.eg4_batteries} x EG4 280Ah (${battKwh} kWh nom) @ $${batteryCost} = $${battTotal.toLocaleString('en-CA')}`,
      service_splitter: `${quantities.distribution_splitters} x 400A Distribution Splitter @ $${splitterCost} = $${splitTotal.toLocaleString('en-CA')}`,
      distribution_panels: `${quantities.distribution_panels_200a} x 200A Electrical Panels @ $${panel200aCost} = $${pnlTotal.toLocaleString('en-CA')}`,
      fused_disconnect: `${quantities.fused_disconnects_400a} x 400A Fused Service Disconnect @ $${fusedDisconnectCost} = $${discTotal.toLocaleString('en-CA')}`,
      electrical_bos_breakers_wiring_insulation: `Breakers, 500kcmil/4/0AWG wiring, conduit, insulation = $${bosCost.toLocaleString('en-CA')}`,
      equipment_subtotal: `$${equipSubtotal.toLocaleString('en-CA')} CAD`,
      total_capital_cost: `$${totalCapex.toLocaleString('en-CA')} CAD (Equipment + BOS)`,
      annual_generator_om: `$${annualGenCost.toLocaleString('en-CA')} CAD / year (${quantities.annual_generator_kwh} kWh/yr, ${quantities.annual_generator_services} services/yr)`,
      lifecycle_10yr_total: `$${lifecycle10yr.toLocaleString('en-CA')} CAD`
    },
    primary_design_recommendation_agent5: agent5Output,
    zero_generator_contingency_agent7: agent7Output
  }
}];
